// The listing screenshots that `just amo-screenshots` uploads, as generated by
// `just screenshots amo` and committed.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";

const scene = JSON.parse(await readFile(new URL("../../docs/screenshots.json", import.meta.url), "utf8"));

test("every AMO screenshot is committed at the size AMO recommends, with a caption", async () => {
  assert.ok(scene.amo.shots.length > 0);
  for (const shot of scene.amo.shots) {
    const png = await readFile(new URL(`../../release/screenshots/${shot.file}`, import.meta.url));
    // A PNG's width and height are the first fields of its IHDR chunk.
    assert.deepEqual([png.readUInt32BE(16), png.readUInt32BE(20)], [scene.amo.width, scene.amo.height], shot.file);
    assert.ok(shot.caption?.trim(), `${shot.file} has no caption`);
  }
  // AMO shows screenshots at up to 1280x800 and crops other shapes to 1.6:1.
  assert.deepEqual([scene.amo.width, scene.amo.height], [1280, 800]);
});
